 void ResetExclusive(){exclusiveCooldown=exclusiveBuff=exclusiveCharge=0;markedEnemy=null;if(renShadow!=null)Dispose(renShadow.gameObject);renShadow=null;renAnchor=pos+Vector2.left*3;if(exclusiveVisual!=null)Dispose(exclusiveVisual.gameObject);exclusiveVisual=null;}
 Enemy ExclusiveTarget(){Enemy target=null;float best=float.MaxValue;Vector2 reference=manualAim?manualAimPoint:pos;foreach(var e in enemies){if((e.p-pos).sqrMagnitude>100)continue;float d=(e.p-reference).sqrMagnitude;if(d<best){best=d;target=e;}}return target;}
 bool TryExclusive(){if(state!=ScreenState.Playing||final3DTransition||exclusiveCooldown>0||exclusiveCharge>0)return false;var target=ExclusiveTarget();if(heroIndex!=2&&target==null){Toast("Aproxime-se de um inimigo para usar a habilidade.");return false;}exclusiveCooldown=ExclusivePeriods[heroIndex];CastVisual();Vector2 aim=WeaponDirection(pos,target);
  if(heroIndex==0){foreach(var e in enemies)if((e.p-pos).sqrMagnitude<36){e.p=Vector2.MoveTowards(e.p,pos,IsBoss(e.type)?.5f:2);e.sprite.transform.position=e.p;}Burst(pos,new Color(.65f,.5f,1),7,.45f,4);DamageArea(pos,5.5f*Area,90*Power,false);}
