 void UpdateRenShadow(){if(heroIndex!=3||world==null)return;renAnchor=ClampExclusivePosition(pos+Vector2.ClampMagnitude(renAnchor-pos,6));if(renShadow==null)renShadow=Sprite("Sombra de Ren • destino do Q",DressedHero(0),renAnchor,1.25f,new Color(.5f,.3f,1,.5f),Depth(renAnchor));renShadow.transform.position=renAnchor;renShadow.sortingOrder=Depth(renAnchor);renShadow.flipX=hero!=null&&hero.flipX;}
 void SyncExclusivePixel(){if(renShadow!=null)Pixel(renShadow,renAnchor,2.15f,.045f,false,true);if(exclusiveVisual!=null&&exclusiveVisual.enabled)Pixel(exclusiveVisual,exclusiveVisual.transform.position,exclusiveVisual.transform.localScale.x,.09f,true,false,12);}
 void DrawExclusiveHud(){if(state==ScreenState.BuildLab)return;Frame(1,26,158,300,37);string status=exclusiveCharge>0?"CARREGANDO "+exclusiveCharge.ToString("0.0")+"s":exclusiveCooldown>0?exclusiveCooldown.ToString("0.0")+"s":"PRONTA";Text("Q • "+ExclusiveNames[heroIndex]+" • "+status,38,163,276,26,Style(12,exclusiveCooldown<=0?cyan:gold,TextAnchor.MiddleCenter,true));GUI.Label(new Rect(26,158,300,37),new GUIContent("",ExclusiveDescriptions[heroIndex]));}
 string VerifyExclusive(){var account=save;bool prior=verifying,aimMode=manualAim;int h0=heroIndex,pet=selectedDragon,curse=selectedCurse;verifying=true;save=new SaveData();selectedDragon=selectedCurse=-1;manualAim=false;
  for(int h=0;h<6;h++){heroIndex=h;StartRun();var e=SpawnEnemy(0,false);e.p=Vector2.right*1.5f;e.hp=e.maxHp=10000;var from=pos;float before=e.hp;manualAimPoint=e.p;if(!TryExclusive()||TryExclusive()||exclusiveCooldown<=0)throw new Exception("Exclusive activation/cooldown failed "+h);if(h==0&&(e.hp>=before||e.p.x>=2))throw new Exception("Astral pull/explosion failed");if(h==1&&(pos.x<=from.x||e.hp>=before))throw new Exception("Wind dash failed");if(h==2){hp=100;invincible=dashTimer=0;HurtPlayer(20,true);if(Mathf.Abs(hp-95)>.01f)throw new Exception("Guardian shield damage reduction failed");}if(h==3&&(pos==from||renAnchor!=from||e.hp>=before))throw new Exception("Shadow swap failed");if(h==4){if(e.hp!=before)throw new Exception("Heavy skill skipped charge");AdvanceExclusive(.64f);if(e.hp!=before)throw new Exception("Heavy charge too short");AdvanceExclusive(.02f);if(e.hp>=before)throw new Exception("Charged heavy hit missing");}if(h==5){Damage(e,20);if(Mathf.Abs(before-e.hp-35)>.01f)throw new Exception("Lunar mark multiplier missing");AdvanceExclusive(6.1f);before=e.hp;Damage(e,20);if(Mathf.Abs(before-e.hp-20)>.01f)throw new Exception("Expired mark still amplifies damage");}state=ScreenState.Paused;float remaining=exclusiveCooldown;Update();if(exclusiveCooldown!=remaining)throw new Exception("Paused exclusive cooldown advanced");StartRun();if(exclusiveCooldown!=0||markedEnemy!=null||exclusiveBuff!=0||exclusiveCharge!=0)throw new Exception("Exclusive leaked into next run");}
  heroIndex=1;StartFinal3DDemo();AdvanceFinalTransition(4);var target=SpawnEnemy(0,false);target.p=pos+Vector2.right*2;target.hp=10000;TryExclusive();FinalCamera();SyncFinal3D();if(!final3DActive||Vector2.Distance(pos,finalOrigin)>19.01f)throw new Exception("Exclusive breaks 2.5D bounds");save=account;heroIndex=h0;selectedDragon=pet;selectedCurse=curse;manualAim=aimMode;verifying=prior;ReturnMenu();return "Six exclusive skills PASS: Q activation, cooldown, pause/reset, astral pull, wind line/dash, shield damage reduction, shadow swap, delayed heavy hit, timed target mark and 2.5D bounds.";
